-- Additive DEV-only purchase-order authority. Do not run until disposable DB confirmation.
CREATE TYPE "OrdenCompraState" AS ENUM ('Borrador', 'Emitida', 'Enviada', 'Parcialmente_recibida', 'Recibida', 'Cancelada');
CREATE TABLE "OrdenCompra" ("id" TEXT NOT NULL, "companyId" TEXT NOT NULL, "proveedorId" TEXT NOT NULL, "proveedorName" TEXT NOT NULL, "total" DECIMAL(14,4) NOT NULL DEFAULT 0, "state" "OrdenCompraState" NOT NULL DEFAULT 'Borrador', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "emitidaAt" TIMESTAMP(3), "enviadaAt" TIMESTAMP(3), "recibidaAt" TIMESTAMP(3), "canceladaAt" TIMESTAMP(3), "observaciones" TEXT, "necesidadCompraIds" TEXT[] DEFAULT ARRAY[]::TEXT[], CONSTRAINT "OrdenCompra_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OrdenCompraItem" ("id" TEXT NOT NULL, "ordenCompraId" TEXT NOT NULL, "stockItemId" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "quantity" DECIMAL(14,4) NOT NULL, "unitPrice" DECIMAL(14,4) NOT NULL, "subtotal" DECIMAL(14,4) NOT NULL, "received" DECIMAL(14,4) NOT NULL DEFAULT 0, "isArticuloZ" BOOLEAN NOT NULL DEFAULT false, "descripcionLibre" TEXT, CONSTRAINT "OrdenCompraItem_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "uq_orden_compra_company_id" ON "OrdenCompra"("companyId", "id"); CREATE INDEX "ix_orden_compra_company_state" ON "OrdenCompra"("companyId", "state"); CREATE INDEX "ix_orden_compra_company_created" ON "OrdenCompra"("companyId", "createdAt" DESC); CREATE INDEX "ix_orden_compra_company_proveedor" ON "OrdenCompra"("companyId", "proveedorId"); CREATE INDEX "ix_orden_compra_item_oc" ON "OrdenCompraItem"("ordenCompraId");
ALTER TABLE "OrdenCompra" ADD CONSTRAINT "OrdenCompra_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "OrdenCompraItem" ADD CONSTRAINT "OrdenCompraItem_ordenCompraId_fkey" FOREIGN KEY ("ordenCompraId") REFERENCES "OrdenCompra"("id") ON DELETE CASCADE ON UPDATE CASCADE;
